def transform(grid):
    h, w = len(grid), len(grid[0])

    # The most frequent color is the background.
    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    bg = max(counts, key=counts.get)

    # Colors forming substantial connected regions are the underlying shapes.
    seen = [[False] * w for _ in range(h)]
    shape_colors = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            size = 0
            while stack:
                y, x = stack.pop()
                size += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            if size >= 4:
                shape_colors.add(color)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] in shape_colors or grid[r][c] == bg:
                continue

            # A stray marker replacing a shape cell leaves three corners of
            # a 2x2 square intact. Restore that missing corner.
            replacement = None
            for top in (r - 1, r):
                for left in (c - 1, c):
                    if not (0 <= top < h - 1 and 0 <= left < w - 1):
                        continue
                    cells = [(top, left), (top + 1, left),
                             (top, left + 1), (top + 1, left + 1)]
                    others = [grid[y][x] for y, x in cells if (y, x) != (r, c)]
                    for color in shape_colors:
                        if all(v == color for v in others):
                            replacement = color
                            break
                    if replacement is not None:
                        break
                if replacement is not None:
                    break

            out[r][c] = replacement if replacement is not None else bg

    return out
